script:
$ErrorActionPreference='Stop'
$taskFile='C:/Users/poin/.elan/toolchains/leanprover--lean4---v4.22.0/lib/lean/libLean.a'
$taskExpected='9A8BCDE682EAC2413F5BF2B211AA04631581A7404FD39857CF589BA0AA0C080F'
$taskRows=@()
foreach($taskMethod in @('buffered-1m-sequential','stock-Get-FileHash')) {
  $taskStart=[DateTime]::UtcNow.ToString('o'); $taskWatch=[Diagnostics.Stopwatch]::StartNew()
  if($taskMethod -ceq 'buffered-1m-sequential') {
    $taskStream=New-Object IO.FileStream($taskFile,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read,1048576,[IO.FileOptions]::SequentialScan)
    $taskSha=[Security.Cryptography.SHA256]::Create()
    try {$taskHash=[BitConverter]::ToString($taskSha.ComputeHash($taskStream)).Replace('-','')}
    finally {$taskSha.Dispose();$taskStream.Dispose()}
  } else {$taskHash=(Get-FileHash -LiteralPath $taskFile -Algorithm SHA256).Hash}
  $taskWatch.Stop()
  $taskRow=[ordered]@{method=$taskMethod;file=$taskFile;bytes=(Get-Item -LiteralPath $taskFile).Length;expectedSHA256=$taskExpected;actualSHA256=$taskHash;accepted=($taskHash -ceq $taskExpected);startedUTC=$taskStart;completedUTC=[DateTime]::UtcNow.ToString('o');seconds=$taskWatch.Elapsed.TotalSeconds;shell=$PSVersionTable.PSVersion.ToString();pid=$PID}
  $taskRows+=,$taskRow
  $taskRow|ConvertTo-Json -Depth 5 -Compress|Write-Output
  [IO.File]::WriteAllText((Join-Path $PSScriptRoot 'hash-buffer-benchmark-result.json'),($taskRows|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
  if(!$taskRow.accepted){throw 'full-byte SHA256 mismatch'}
}
